const { chromium } = require('playwright');
const fs   = require('fs');
const path = require('path');

const BASE_URL        = 'https://staging.247software.com';
const ET_URL          = `${BASE_URL}/#/setup-navigation/event-types`;
const USERNAME        = 'Pranay';
const PASSWORD        = 'Pranay@1234';
const SCREENSHOTS_DIR = path.resolve(__dirname, '../screenshots');
if (!fs.existsSync(SCREENSHOTS_DIR)) fs.mkdirSync(SCREENSHOTS_DIR, { recursive: true });

const results = [];

function record(id, title, status, detail, screenshot) {
  const e = { id, title, status, detail: detail ? String(detail).slice(0, 600) : null, screenshot: screenshot || null, timestamp: new Date().toISOString() };
  results.push(e);
  const lbl = status === 'PASS' ? 'PASS' : status === 'SKIP' ? 'SKIP' : 'FAIL';
  console.log(`[${lbl}] ${id} — ${title}${detail ? ' | ' + String(detail).slice(0, 150) : ''}`);
}

async function launch() {
  return chromium.launch({ headless: true, args: ['--no-sandbox', '--disable-setuid-sandbox'] });
}

async function setupPage(browser, url) {
  const ctx  = await browser.newContext({ ignoreHTTPSErrors: true });
  const page = await ctx.newPage();
  page.setDefaultTimeout(25000);
  await page.goto(BASE_URL, { waitUntil: 'domcontentloaded', timeout: 30000 });
  await page.waitForTimeout(1500);
  await page.fill('#username', USERNAME);
  await page.fill('#password', PASSWORD);
  await Promise.all([
    page.waitForResponse(r => r.url().includes('/authenticate') && r.status() === 200, { timeout: 20000 }),
    page.click('#login_btn')
  ]);
  await page.waitForTimeout(4000);
  if (url) { await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 20000 }); await page.waitForTimeout(4000); }
  return page;
}

async function waitForGrid(page) {
  await page.waitForSelector('.ag-row', { timeout: 12000 }).catch(() => {});
  await page.waitForTimeout(1500);
}

async function selectFacility(page) {
  await page.click('#facilityDropDown');
  await page.waitForTimeout(1500);
  await page.fill('#facilityDropDown input.combobox-input-text', 'QA');
  await page.waitForTimeout(1500);
  await page.evaluate(() => {
    const items = Array.from(document.querySelectorAll('.virtual-list-item'));
    const qa = items.find(i => i.textContent.trim().includes('QA_Facilities') && i.getBoundingClientRect().width > 0);
    if (qa) qa.click();
  });
  await page.waitForTimeout(1000);
}

// Helper: click the VISIBLE confirm button (not zero-size ones)
async function clickVisibleButton(page, selector) {
  await page.evaluate((sel) => {
    const buttons = Array.from(document.querySelectorAll(sel));
    const visible = buttons.find(b => {
      const r = b.getBoundingClientRect();
      return r.width > 0 && r.height > 0;
    });
    if (visible) visible.click();
    else throw new Error('No visible button found for: ' + sel);
  }, selector);
}

async function shot(page, id) {
  const p = path.join(SCREENSHOTS_DIR, `${id}.png`);
  try { await page.screenshot({ path: p, fullPage: true }); } catch (_) {}
  return p;
}

// TC-001
async function TC001() {
  const [id, title] = ['TC-001', 'Navigate to Event Types from Setup menu'];
  const browser = await launch();
  try {
    const page = await setupPage(browser, `${BASE_URL}/#/setup`);
    await page.waitForTimeout(2000);
    const etLink = page.locator('a[href="#/setup-navigation/event-types"], label[id="/setupnavigation/eventtypes"]').first();
    await etLink.waitFor({ state: 'visible', timeout: 10000 });
    await etLink.click();
    await page.waitForTimeout(3000);
    const url = page.url();
    const pass = url.includes('event-types');
    record(id, title, pass ? 'PASS' : 'FAIL', `URL: ${url}`, await shot(page, id));
  } catch (e) { record(id, title, 'FAIL', e.message, path.join(SCREENSHOTS_DIR, `${id}.png`)); }
  finally { await browser.close(); }
}

