// TC-007
async function TC007() {
  const [id, title] = ['TC-007', 'Delete an Event Type successfully'];
  const browser = await launch();
  try {
    const page = await setupPage(browser, ET_URL);
    await waitForGrid(page);
    const deleteBtns = page.locator('span.far.fa-trash-alt.deleteButton');
    if (await deleteBtns.count() === 0) { return record(id, title, 'SKIP', 'No delete button', await shot(page, id)); }
    const rowsBefore = (await page.evaluate(() => Array.from(document.querySelectorAll('.ag-row')).filter(r => r.innerText.trim().length > 0).length));
    let deleteApiOk = false;
    page.waitForResponse(r => r.url().includes('/delete') && r.status() === 200, { timeout: 10000 }).then(() => { deleteApiOk = true; }).catch(() => {});
    await deleteBtns.first().click();
    await page.waitForTimeout(3000);
    // Click the VISIBLE confirm delete button
    await clickVisibleButton(page, 'button.rounded.modal-confirm-button');
    await page.waitForTimeout(6000);
    const rowsAfter = (await page.evaluate(() => Array.from(document.querySelectorAll('.ag-row')).filter(r => r.innerText.trim().length > 0).length));
    const pass = rowsAfter < rowsBefore || deleteApiOk;
    record(id, title, pass ? 'PASS' : 'FAIL', pass ? 'Row count reduced: ' + rowsBefore + ' -> ' + rowsAfter + ' deleteApi=' + deleteApiOk : 'Not confirmed: rows=' + rowsBefore + '->' + rowsAfter, await shot(page, id));
  } catch (e) { record(id, title, 'FAIL', e.message, path.join(SCREENSHOTS_DIR, `${id}.png`)); }
  finally { await browser.close(); }
}

