// TC-014
async function TC014() {
  const [id, title] = ['TC-014', 'Search with no matching term shows empty state'];
  const browser = await launch();
  try {
    const page = await setupPage(browser, ET_URL);
    await waitForGrid(page);
    const searchInput = page.locator('#setup-header-grid-quick-search');
    await searchInput.waitFor({ state: 'visible', timeout: 8000 });
    await searchInput.fill('XYZNONEXISTENT999');
    await page.waitForTimeout(3500);
    // Check visible row content (not hidden ag-grid rows)
    const gridRowText = await page.evaluate(() => {
      const rows = Array.from(document.querySelectorAll('.ag-row'));
      return rows.map(r => {
        const rect = r.getBoundingClientRect();
        const vis = rect.width > 0 && rect.height > 0;
        return { text: r.innerText.trim().slice(0, 40), visible: vis };
      });
    });
    const visibleRows = gridRowText.filter(r => r.visible);
    console.log('  Visible rows after no-match search:', JSON.stringify(visibleRows));
    // The grid may show rows but with empty content if client-side filtered
    const nonEmptyVisible = visibleRows.filter(r => r.text.length > 0);
    const pass = nonEmptyVisible.length === 0 || !nonEmptyVisible.some(r => r.text.includes('24/7 Mode'));
    record(id, title, pass ? 'PASS' : 'FAIL',
      `Visible non-empty rows: ${nonEmptyVisible.length}. Contents: ${JSON.stringify(nonEmptyVisible.slice(0,3))}`, await shot(page, id));
  } catch (e) { record(id, title, 'FAIL', e.message, path.join(SCREENSHOTS_DIR, `${id}.png`)); }
  finally { await browser.close(); }
}

